insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'oth_elps_v1'
from (values
('120.20.d.1.A ',1,'A teacher says the words ship and sheep. Which listening skill is the student using to tell them apart?','["hearing the different vowel sounds", "counting the letters", "reading the page upside down", "drawing a picture"]'::jsonb,0,'Distinguishing sounds means noticing small differences in speech.','original'),
('120.20.d.1.A ',2,'A student hears a question with rising intonation at the end. What does this usually tell the listener?','["The speaker is finished talking.", "The speaker is asking a question.", "The speaker is whispering a secret.", "The speaker is angry."]'::jsonb,1,'Intonation patterns help listeners understand meaning.','original'),
('120.20.d.1.B',2,'During science class a teacher says, The seed will germinate. A student who understands content vocabulary knows germinate means:','["fall to the ground", "get washed away", "start to grow", "turn red"]'::jsonb,2,'Content-area vocabulary helps students follow lessons.','original'),
('120.20.d.1.B',2,'Which word from math class would a student need to know to follow the instruction, Find the sum?','["the", "find", "class", "sum"]'::jsonb,3,'Sum is a content-area word meaning the result of adding.','original'),
('120.20.d.1.C',1,'The teacher says, Put your pencil in the box and then stand up. What should the student do first?','["put the pencil in the box", "open the door", "stand up", "sit down"]'::jsonb,0,'Following oral directions means doing each step in order.','original'),
('120.20.d.1.C',2,'Which student is following directions with accuracy?','["the student who talks during directions", "the student who listens to every step and does them in order", "the student who skips the middle step", "the student who does the last step first"]'::jsonb,1,'Accurate direction following means listening carefully.','original'),
('120.20.d.1.D',2,'If someone says, It''s raining cats and dogs, what do the words mean?','["Pets are playing outside.", "It is a sunny day.", "It is raining very hard.", "Animals are falling from the sky."]'::jsonb,2,'Figurative language is understood by using context.','original'),
('120.20.d.1.D',2,'The word bat can mean an animal or a sports tool. How can a listener tell which meaning is used?','["by asking nobody", "by guessing at random", "by ignoring the word", "by using the other words in the sentence"]'::jsonb,3,'Context clues help with words with multiple meanings.','original'),
('120.20.d.1.E',2,'After listening to a story, which shows good listening comprehension?','["retelling the main events in order", "drawing a random shape", "saying the story was long", "naming only the title"]'::jsonb,0,'Comprehension means understanding what was heard.','original'),
('120.20.d.1.E',2,'During a class discussion, a student listens and then answers the question the teacher asked. This shows:','["a math problem", "listening comprehension", "a science fair", "a spelling test"]'::jsonb,1,'Responding correctly shows understanding.','original'),
('120.20.d.1.F',2,'A student watches a short video about weather and learns new words. This is an example of getting meaning from:','["a handwritten letter", "a math worksheet", "auditory multimedia", "a dictionary only"]'::jsonb,2,'Videos and audio build vocabulary.','original'),
('120.20.d.1.F',3,'Which is an auditory multimedia source?','["a plain worksheet", "a photograph with no sound", "a paper map", "a recorded story played on a tablet"]'::jsonb,3,'Auditory means related to sound.','original'),
('120.20.d.2.A',2,'A student practicing pronunciation sees the word knee. Which letter is not pronounced?','["k", "e", "a", "n"]'::jsonb,0,'The k in knee is not pronounced.','original'),
('120.20.d.2.A',2,'When practicing English pronunciation, which word has a long a sound like the name of the letter A?','["cup", "cake", "cut", "cat"]'::jsonb,1,'The a in cake says its name.','original'),
('120.20.d.2.B',2,'A student presents on how liquid water turns into a gas. Which word is the science vocabulary term for this?','["very", "then", "evaporation", "also"]'::jsonb,2,'Evaporation is a science term.','original'),
('120.20.d.2.B',2,'Which sentence uses a math content word correctly?','["The triangle can sing.", "The triangle is a color.", "The triangle is tasty.", "The triangle has three sides."]'::jsonb,3,'Using subject words correctly shows understanding.','original'),
('120.20.d.2.C',2,'Which connecting word joins these ideas: I like apples ___ I like pears?','["and", "behind", "under", "because of"]'::jsonb,0,'And joins two similar ideas.','original'),
('120.20.d.2.C',3,'Which sentence is a question?','["The library is big.", "Where is the library?", "I love books.", "Please be quiet."]'::jsonb,1,'Questions ask for information and end with a question mark.','original'),
('120.20.d.2.D',2,'Which greeting is best to say to a teacher?','["Hey, you.", "What''s up, dude.", "Good morning, Ms. Lee.", "Sup."]'::jsonb,2,'Register means choosing words that fit the person and place.','original'),
('120.20.d.2.D',3,'Register means:','["a type of register in a store", "the sound of a bell", "spelling every word perfectly", "choosing language that fits the situation and listener"]'::jsonb,3,'Formal and informal talk are different registers.','original'),
('120.20.d.2.E',3,'Which sentence adds more detail?','["The big brown dog ran quickly across the green yard.", "Dog ran.", "Ran dog.", "The dog ran."]'::jsonb,0,'More specific words give more detail.','original'),
('120.20.d.2.E',3,'When you describe a pet to a friend, which is the best way to be specific?','["say nothing", "say its color, size and what it likes to do", "say only the word pet", "say it is nice"]'::jsonb,1,'Specific details help the listener picture it.','original'),
('120.20.d.2.F',2,'When a friend finishes explaining a game, which is a good follow-up question?','["I am hungry.", "Close the door.", "How do you win?", "The sky is blue."]'::jsonb,2,'Asking questions shows you are listening.','original'),
('120.20.d.2.F',2,'To restate what a classmate said, you:','["walk away", "stay silent", "say something unrelated", "say it again in your own words"]'::jsonb,3,'Restating shows understanding.','original'),
('120.20.d.3.A',1,'In English, which direction do readers move across a line of text?','["from left to right", "from bottom to top", "from right to left", "in a circle"]'::jsonb,0,'English text is read left to right and top to bottom.','original'),
('120.20.d.3.A',1,'After reading a line, where do you go next on a page?','["to the top of the page", "to the next line below", "to the back cover", "to the right edge"]'::jsonb,1,'Readers move top to bottom.','original'),
('120.20.d.3.B',2,'Which letters make the first sound in the word chip?','["p", "h", "ch", "c"]'::jsonb,2,'The letters ch together make one sound.','original'),
('120.20.d.3.B',2,'Decoding a word means:','["skipping the word", "guessing the picture only", "spelling it backward", "using letter sounds to read it"]'::jsonb,3,'Decoding links sounds to letters.','original'),
('120.20.d.3.C',2,'Which English word is a cognate of the Spanish word elefante?','["elephant", "apple", "pencil", "horse"]'::jsonb,0,'Cognates look and sound similar in two languages.','original'),
('120.20.d.3.C',3,'Which is a high-frequency word that appears in many texts?','["photosynthesis", "the", "democracy", "triangle"]'::jsonb,1,'High-frequency words are common.','original'),
('120.20.d.3.D',3,'The sentence He has a heart of gold means the person is:','["sick", "very rich in gold", "very kind", "made of metal"]'::jsonb,2,'Idioms have meanings beyond the exact words.','original'),
('120.20.d.3.D',3,'What does the idiom piece of cake mean?','["a gift", "a dessert", "a big problem", "something very easy"]'::jsonb,3,'Idioms must be read using context.','original'),
('120.20.d.3.E',2,'Before reading a book, which strategy helps?','["looking at the title and pictures", "skipping to the end only", "closing the book", "covering the pictures"]'::jsonb,0,'Previewing text features gets readers ready.','original'),
('120.20.d.3.E',3,'Connecting to prior knowledge before reading means:','["reading backward", "thinking about what you already know on the topic", "copying a friend", "memorizing the book"]'::jsonb,1,'Prior knowledge supports comprehension.','original'),
('120.20.d.3.F',3,'A reader sees a bold word with a picture next to it. How can the picture help?','["It hides the meaning.", "It is a puzzle.", "It gives a visual clue to the word''s meaning.", "It means the word is wrong."]'::jsonb,2,'Visual supports help understand texts.','original'),
('120.20.d.3.F',3,'Which is a contextual support that helps with an unknown word?','["the book cover color", "the publisher", "the page number", "the sentences around the word"]'::jsonb,3,'Context clues are found near the word.','original'),
('120.20.d.3.G',2,'After reading, which shows good comprehension?','["retelling the story in your own words", "counting the pictures", "naming the page number", "listing the font"]'::jsonb,0,'Retelling shows understanding.','original'),
('120.20.d.3.G',3,'Making a connection to a text means:','["changing the ending randomly", "relating the story to your own life or another story", "copying the title", "skipping chapters"]'::jsonb,1,'Connections help understanding.','original'),
('120.20.d.3.H',2,'Reading with fluency means reading:','["very slowly word by word", "in a whisper only", "smoothly with few mistakes", "with no expression"]'::jsonb,2,'Fluent readers read accurately and smoothly.','original'),
('120.20.d.3.H',3,'Which shows both fluency and comprehension?','["saying numbers out loud", "reading only the first word", "reading fast without understanding", "reading a paragraph smoothly and explaining what it said"]'::jsonb,3,'Fluency plus comprehension is the goal.','original'),
('120.20.d.4.A',2,'A student wants to write the word fish. Which letters match the first sound?','["f", "t", "s", "h"]'::jsonb,0,'The first sound in fish is /f/.','original'),
('120.20.d.4.A',2,'Which word starts with the same sound as sun?','["top", "sit", "hat", "map"]'::jsonb,1,'Both start with /s/.','original'),
('120.20.d.4.B',2,'Which is the correct spelling?','["freind", "frend", "friend", "freend"]'::jsonb,2,'Friend has ie after fr.','original'),
('120.20.d.4.B',2,'A common spelling pattern is i before e except after c. Which word follows the pattern?','["beleve", "beleive", "belive", "believe"]'::jsonb,3,'Believe follows i before e.','original'),
('120.20.d.4.C',2,'A student writing about plants should use which content word?','["root", "rock", "rope", "road"]'::jsonb,0,'Root is a plant part.','original'),
('120.20.d.4.C',2,'Which high-frequency word is spelled correctly?','["siad", "said", "sayd", "sed"]'::jsonb,1,'Said is a common irregular spelling.','original'),
('120.20.d.4.D',3,'Which connecting word best completes: I wanted to play, ___ it was raining.','["and then", "so far", "but", "because of"]'::jsonb,2,'But shows contrast.','original'),
('120.20.d.4.E ',1,'Names of people always start with a capital letter. Which of these is a person''s name?','["with", "store", "went", "Sara"]'::jsonb,3,'Names of people are capitalized.','original'),
('120.20.d.4.E ',2,'What punctuation mark ends a question?','["?", ",", ".", "!"]'::jsonb,0,'A question mark ends a question.','original'),
('120.20.d.4.F',2,'When you write to describe, you should:','["copy another text", "use details that help the reader picture it", "write one word", "leave out the topic"]'::jsonb,1,'Descriptive writing uses detail.','original'),
('120.20.d.4.F',3,'A student writes, First I mixed the paint. Then I painted the sky. This is writing to:','["describe a smell", "persuade the reader to buy", "explain or narrate steps", "list rules"]'::jsonb,2,'Sequence words show steps.','original'),
('120.21.d.1.A',2,'A listener hears the stress change in record (noun) and record (verb). The listener is noticing:','["the spelling only", "handwriting", "page layout", "stress and intonation patterns"]'::jsonb,3,'Stress and intonation can change meaning.','original'),
('120.21.d.1.A',3,'A rising voice at the end of a sentence often signals:','["a question", "a pause for lunch", "a command", "the end of a story"]'::jsonb,0,'Intonation helps listeners interpret.','original'),
('120.21.d.1.B',3,'The Latin root aqua means water. What does aquarium most likely mean?','["a kind of rock", "a place for water animals or plants", "a type of desert", "a fire tool"]'::jsonb,1,'Roots help decode meaning.','original'),
('120.21.d.1.B',3,'The prefix un- means not. What does unhappy mean?','["very happy", "before happy", "not happy", "happy again"]'::jsonb,2,'Word analysis uses prefixes.','original'),
('120.21.d.1.C',2,'A teacher gives three oral directions. A student who responds accurately:','["does them randomly", "does the last one only", "asks to repeat each time", "does all three in the order given"]'::jsonb,3,'Accuracy means following each step.','original'),
('120.21.d.1.C',3,'If a lab instruction says, Measure, then record, then clean up, what is done second?','["record the measurement", "clean up", "leave", "measure"]'::jsonb,0,'Order matters in directions.','original'),
('120.21.d.1.D',3,'What does it mean if a speaker says, That test was a breeze?','["It was long.", "It was easy.", "It was windy.", "It was cancelled."]'::jsonb,1,'Figurative language uses context.','original'),
('120.21.d.1.D',3,'A speaker uses formal register in a meeting. Which phrase fits?','["Yeah, whatever.", "Yo, listen up.", "I would like to propose an idea.", "Dude, check this."]'::jsonb,2,'Register changes by setting.','original'),
('120.21.d.1.E',3,'Which shows strong listening comprehension after a lecture?','["remembering only the title", "leaving early", "repeating random words", "summarizing the main points"]'::jsonb,3,'Comprehension means understanding the main ideas.','original'),
('120.21.d.1.E',3,'In a group discussion, a student restates a classmate''s idea before adding their own. This shows:','["active listening", "avoiding the topic", "daydreaming", "interrupting"]'::jsonb,0,'Active listening includes restating.','original'),
('120.21.d.1.F',3,'A student watches a documentary with subtitles to learn new terms. This is an example of:','["copying notes without watching", "using auditory multimedia to build language", "silent reading only", "guessing"]'::jsonb,1,'Audio and video build language.','original'),
('120.21.d.1.F',3,'Which source gives both spoken language and visuals?','["a muted picture", "a blank screen", "a recorded lecture with slides", "a plain printed page"]'::jsonb,2,'Multimedia adds context.','original'),
('120.21.d.2.A',3,'Which word contains a letter that is not pronounced?','["lift", "rate", "trip", "write"]'::jsonb,3,'The w in write is silent.','original'),
('120.21.d.2.A',3,'The word photograph is a cognate in Spanish as fotografía. This means the words:','["look and sound alike and share meaning", "have unrelated meanings", "are spelled the same in all languages", "are opposites"]'::jsonb,0,'Cognates connect languages.','original'),
('120.21.d.2.B',3,'A student presenting on a poem uses the term metaphor. This shows use of:','["slang", "content-area vocabulary", "random words", "only math words"]'::jsonb,1,'Content words show subject knowledge.','original'),
('120.21.d.2.B',3,'Which word is a social studies content term?','["whisk", "quartet", "legislature", "swatch"]'::jsonb,2,'Legislature relates to government.','original'),
('120.21.d.2.C',3,'Which transition word shows contrast?','["next", "for example", "therefore", "however"]'::jsonb,3,'However signals a difference.','original'),
('120.21.d.2.C',3,'Which transition word shows result?','["as a result", "in contrast", "meanwhile", "on the other hand"]'::jsonb,0,'As a result shows cause and effect.','original'),
('120.21.d.2.D',3,'In a class presentation, which language is most appropriate?','["slang and shortened texting words", "complete sentences with polite academic words", "whispered fragments", "only gestures"]'::jsonb,1,'Presentations call for formal register.','original'),
('120.21.d.2.D',3,'Which sentence suits a casual chat with a friend?','["Kindly advise regarding your schedule.", "Pursuant to my earlier note.", "Hey, want to hang out later?", "I request your presence at an event."]'::jsonb,2,'Informal register fits friends.','original'),
('120.21.d.2.E',4,'Which sentence best justifies an opinion?','["It is open.", "The library is good.", "I like it.", "I think the library should open longer because many students need quiet space after school."]'::jsonb,3,'Justifying includes reasons.','original'),
('120.21.d.2.E',4,'To evaluate a plan orally, a speaker should:','["state strengths and weaknesses with reasons", "stay quiet", "describe unrelated facts", "say only yes"]'::jsonb,0,'Evaluation weighs pros and cons.','original'),
('120.21.d.2.F',3,'To respond to a speaker, a student might say:','["Stop talking.", "Can you explain what you mean by that term?", "That is all.", "I was not listening."]'::jsonb,1,'Questions show engagement.','original'),
('120.21.d.2.F',3,'Paraphrasing a speaker''s point means:','["repeating word for word", "ignoring the point", "saying the idea in your own words", "changing the topic"]'::jsonb,2,'Restating checks understanding.','original'),
('120.21.d.3.A',1,'Text in English is read in which direction?','["right to left", "diagonally only", "bottom to top", "left to right and top to bottom"]'::jsonb,3,'This is the English print convention.','original'),
('120.21.d.3.A',2,'When reading a column of text, where does a reader start?','["at the top left", "in the middle", "at the last word", "at the bottom right"]'::jsonb,0,'Readers start top-left.','original'),
('120.21.d.3.B',3,'Which word has three syllables?','["cat", "computer", "ship", "table"]'::jsonb,1,'Com-pu-ter has three syllables.','original'),
('120.21.d.3.B',3,'The suffix -ful means full of. What does hopeful mean?','["hope again", "without hope", "full of hope", "before hope"]'::jsonb,2,'Affix knowledge helps decoding.','original'),
('120.21.d.3.C',3,'The Greek root bio means life. What does biology study?','["stars", "rocks", "numbers", "living things"]'::jsonb,3,'Roots reveal word meaning.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Other Texas Essential Knowledge and Skills' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'oth_elps_v1'
from (values
('120.21.d.3.C',3,'Which prefix means not?','["in-", "mid-", "re-", "pre-"]'::jsonb,0,'In- as in incorrect means not.','original'),
('120.21.d.3.D',3,'What does it mean to say a student is on thin ice?','["The student is cold.", "The student is in a risky situation.", "The student is skating.", "The student is hungry."]'::jsonb,1,'Idioms have figurative meanings.','original'),
('120.21.d.3.D',3,'The phrase The classroom was a zoo suggests:','["it was a museum", "it was empty", "the room was noisy and chaotic", "animals lived there"]'::jsonb,2,'This is a metaphor.','original'),
('120.21.d.3.E',3,'Which pre-reading strategy helps most with a science article?','["ignoring the pictures", "reading only the title", "skipping to the end", "previewing headings and diagrams"]'::jsonb,3,'Previewing builds a mental map.','original'),
('120.21.d.3.E',3,'Organizing ideas before reading can be done with:','["a graphic organizer", "a blank page only", "nothing", "random notes"]'::jsonb,0,'Graphic organizers help structure.','original'),
('120.21.d.3.F',3,'A diagram next to a text about the water cycle helps the reader by:','["making text longer", "showing the process visually", "replacing all words", "hiding the meaning"]'::jsonb,1,'Visuals support comprehension.','original'),
('120.21.d.3.F',3,'If a word is unfamiliar, a reader can look at nearby sentences. This is using:','["the author''s name", "the page number", "context clues", "a guess only"]'::jsonb,2,'Context supports meaning.','original'),
('120.21.d.3.G',3,'Which is a summary?','["a list of unknown words", "a single quote", "a full copy of the text", "a short statement of the main ideas of a text"]'::jsonb,3,'Summaries condense main ideas.','original'),
('120.21.d.3.G',3,'Paraphrasing a passage means:','["restating it in your own words", "reading it faster", "skipping it", "copying it exactly"]'::jsonb,0,'Paraphrases keep meaning with new wording.','original'),
('120.21.d.3.H',3,'Prosody in reading refers to:','["page count", "expression, phrasing and rhythm", "book size", "word count"]'::jsonb,1,'Prosody adds meaning to reading aloud.','original'),
('120.21.d.3.H',3,'Which shows fluent reading with prosody?','["reading too quietly to hear", "reading in a flat voice", "reading with natural pacing and changes in voice", "reading one word at a time"]'::jsonb,2,'Prosody sounds like natural speech.','original'),
('120.21.d.4.A',2,'Which word can be spelled by matching sounds to letters?','["knight", "gnome", "wrench", "map"]'::jsonb,3,'Map is a regular phonetic word.','original'),
('120.21.d.4.A',3,'Which letters can represent the /f/ sound?','["f and ph", "t and d", "k and c", "m and n"]'::jsonb,0,'Ph says /f/ in words like phone.','original'),
('120.21.d.4.B',3,'A rule says to drop the silent e before adding -ing. Which fits the rule?','["hopping", "hoping", "hopeing", "hoppping"]'::jsonb,1,'Hope becomes hoping.','original'),
('120.21.d.4.C',3,'Which sentence uses high-frequency and content words well?','["Plants stuff thing.", "Plant is things.", "Plants need sunlight and water to grow.", "Grow sun sun."]'::jsonb,2,'Clear sentences combine common and content words.','original'),
('120.21.d.4.C',3,'Which word is a content-area term for science?','["whisper", "napkin", "carpet", "ecosystem"]'::jsonb,3,'Ecosystem is a science word.','original'),
('120.21.d.4.D',3,'Which sentence uses a transition word?','["First, we gathered materials.", "Materials we gathered.", "Gathered materials we.", "We gathered materials."]'::jsonb,0,'First is a sequence transition.','original'),
('120.21.d.4.D',3,'Which transition word fits: I studied hard; ___, I passed the test.','["however", "therefore", "meanwhile", "for instance"]'::jsonb,1,'Therefore shows result.','original'),
('120.21.d.4.E',2,'Which is the correct abbreviation for Doctor before a name?','["Dor", "Dctr", "Dr.", "Docr"]'::jsonb,2,'Dr. is the standard abbreviation.','original'),
('120.21.d.4.E',3,'Which abbreviation is correct for Street?','["Str", "Strt", "Stre.", "St."]'::jsonb,3,'St. is a standard abbreviation.','original'),
('120.21.d.4.F',3,'A student writes, I believe school uniforms should be optional because they limit self-expression. This is writing to:','["justify an opinion with a reason", "list directions", "describe a smell", "narrate a story"]'::jsonb,0,'The writer gives a claim and reason.','original'),
('120.21.d.4.F',3,'To support an explanation with evidence, a writer should add:','["more adjectives only", "specific details or facts", "unrelated jokes", "a longer title"]'::jsonb,1,'Evidence strengthens writing.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
